"""The per-widget registry and its generated files (card MQ2).

The old widget flow appended to shared lines in project.yml, the bundle, the
settings enum/labels, WIDGET_COVERAGE.md and the decode harness. These tests pin
the replacement:

  * one JSON file per widget is the source of truth, and --check passes on the
    committed tree;
  * the widget directory is a computed source entry in BOTH specs, so adding a
    widget file does not edit either project.yml;
  * the generated files really are append-only record lists: simulate two cards
    adding different widgets, merge their generated output with
    ``git merge-file --union``, and require both records to survive with one
    header and balanced Swift braces.
"""

from __future__ import annotations

import copy
import importlib.util
import re
import subprocess
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
MODULE_PATH = REPO / "ios-app" / "scripts" / "widget_registry.py"

spec = importlib.util.spec_from_file_location("widget_registry", MODULE_PATH)
assert spec and spec.loader
wr = importlib.util.module_from_spec(spec)
spec.loader.exec_module(wr)


def fake_widget(base: dict, serial: int) -> dict:
    item = copy.deepcopy(base)
    item.update(
        {
            "id": f"test_widget_{serial}",
            "order": 15 + serial,
            "bundle_order": 15 + serial,
            "surface_case": f"widgetTest{serial}",
            "surface_raw": f"widget.test{serial}",
            "display_name": f"Test Widget {serial}",
            "icon": "testtube.2",
            "widget_type": f"TestWidget{serial}",
            "sources": [],
            "coverage_ios": [f"cell {serial} {i}" for i in range(6)],
            "coverage_macos": [f"mac cell {serial} {i}" for i in range(4)],
            "coverage_source": f"`Test{serial}.swift`",
            "decode_hook": f"checkTest{serial}Widget",
        }
    )
    return item


def merge_union(base: str, ours: str, theirs: str, tmp_path: Path) -> str:
    current = tmp_path / "current"
    base_file = tmp_path / "base"
    other = tmp_path / "other"
    current.write_text(ours)
    base_file.write_text(base)
    other.write_text(theirs)
    subprocess.run(
        ["git", "merge-file", "--union", str(current), str(base_file), str(other)],
        check=True,
        capture_output=True,
        text=True,
    )
    return current.read_text()


def target_block(text: str, target: str) -> str:
    rest = text.split("\ntargets:\n", 1)[1]
    idx = rest.index(f"\n  {target}:") + 1
    block = rest[idx:]
    return re.split(r"\n  [A-Za-z]\w*:\n", block, maxsplit=1)[0]


def test_registry_check_passes_on_committed_tree():
    manifests, shared = wr.load_manifests()
    assert len(manifests) >= 9
    assert wr.check(manifests, shared) == []
    assert wr.check_project_specs() == []


def test_widget_targets_compute_the_source_list_from_the_directory():
    ios = target_block((REPO / "ios-app" / "project.yml").read_text(), "HSCCWidgets")
    mac = target_block((REPO / "macos-app" / "project.yml").read_text(), "HSCCMacWidgets")
    assert "- path: Sources/HSCCWidgets\n" in ios
    assert "- path: ../ios-app/Sources/HSCCWidgets\n" in mac
    assert "- path: Sources/HSCCWidgets/" not in ios
    assert "- path: ../ios-app/Sources/HSCCWidgets/" not in mac


def test_union_merge_keeps_two_new_widgets(tmp_path):
    manifests, _ = wr.load_manifests()
    base_widget = next(m for m in manifests if m["kind"] == "widget")
    a = fake_widget(base_widget, 1)
    b = fake_widget(base_widget, 2)

    cases = [
        ("enum", wr.render_enum, "surface_case"),
        ("bundle", wr.render_bundle, "widget_type"),
        ("labels", wr.render_labels, "surface_case"),
        ("coverage", wr.render_coverage, "coverage_source"),
        ("decode", wr.render_decode, "decode_hook"),
    ]
    for name, render, field in cases:
        base = render(manifests)
        ours = render(manifests + [a])
        theirs = render(manifests + [b])
        directory = tmp_path / name
        directory.mkdir()
        merged = merge_union(base, ours, theirs, directory)
        assert a[field] in merged, name
        assert b[field] in merged, name
        # The header is context shared by both branches, never duplicated.
        assert merged.count("GENERATED by ios-app/scripts/widget_registry.py") == 1, name
        if name != "coverage":
            assert merged.count("{") == merged.count("}"), name


def test_union_merge_parses_both_new_records(tmp_path):
    """The same merge, then parse the generated files' record lines."""
    manifests, _ = wr.load_manifests()
    base_widget = next(m for m in manifests if m["kind"] == "widget")
    a = fake_widget(base_widget, 3)
    b = fake_widget(base_widget, 4)

    for path, render, pattern in [
        (wr.ENUM_FILE, wr.render_enum, r'^\s*case ([A-Za-z]\w* = "[^"]+")$'),
        (wr.BUNDLE_FILE, wr.render_bundle, r"^\s*([A-Za-z]\w*\(\))$"),
        (wr.LABELS_FILE, wr.render_labels,
         r'^\s*case \.([A-Za-z]\w*: return "[^"]+")$'),
        (wr.DECODE_FILE, wr.render_decode, r"^\s*([A-Za-z]\w*\(c\))$"),
    ]:
        base = path.read_text()
        ours = render(manifests + [a])
        theirs = render(manifests + [b])
        merged = merge_union(base, ours, theirs, tmp_path)
        records = re.findall(pattern, merged, re.M)
        assert len(records) == len(set(records)), path.name
        if path is wr.ENUM_FILE:
            assert f'{a["surface_case"]} = "{a["surface_raw"]}"' in records
            assert f'{b["surface_case"]} = "{b["surface_raw"]}"' in records
        elif path is wr.BUNDLE_FILE:
            assert f'{a["widget_type"]}()' in records
            assert f'{b["widget_type"]}()' in records
        elif path is wr.DECODE_FILE:
            assert f'{a["decode_hook"]}(c)' in records
            assert f'{b["decode_hook"]}(c)' in records
